<?php
require_once __DIR__.'/includes/auth.php';require_auth();$u=current_user();
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();db()->prepare('DELETE FROM favorites WHERE user_id=? AND asset_id=?')->execute([$u['id'],(int)($_POST['asset_id']??0)]);flash('success','Removed from favorites.');redirect('favorites.php');}
$stmt=db()->prepare("SELECT a.*,c.name category_name FROM favorites f JOIN assets a ON a.id=f.asset_id LEFT JOIN categories c ON c.id=a.category_id WHERE f.user_id=? AND a.deleted_at IS NULL ORDER BY f.created_at DESC");$stmt->execute([$u['id']]);$assets=array_values(array_filter($stmt->fetchAll(),fn($a)=>asset_can_view($a,$u)));$pageTitle='My favorites';$pageSubtitle='Quick access to the assets you saved';require __DIR__.'/includes/header.php';?>
<div class="row g-4"><?php foreach($assets as $a):?><div class="col-sm-6 col-xl-4 col-xxl-3"><div class="card asset-card h-100"><a class="asset-thumb" href="<?=e(url('asset-details.php?id='.$a['id']))?>"><?php if(in_array($a['file_extension'],['jpg','jpeg','png','gif','webp'],true)):?><img src="<?=e(url('preview.php?id='.$a['id']))?>" alt="<?=e($a['title'])?>"><?php else:?><i class="bi <?=e(asset_icon($a['file_extension']))?>"></i><?php endif;?></a><div class="card-body"><div class="d-flex"><div class="flex-grow-1 overflow-hidden"><a class="fw-semibold text-dark text-decoration-none d-block text-truncate" href="<?=e(url('asset-details.php?id='.$a['id']))?>"><?=e($a['title'])?></a><small class="text-muted"><?=e($a['category_name']??'Uncategorized')?> · <?=e(human_file_size((int)$a['file_size']))?></small></div><form method="post"><?=csrf_field()?><input type="hidden" name="asset_id" value="<?=$a['id']?>"><button class="btn btn-sm text-warning" title="Remove favorite"><i class="bi bi-star-fill"></i></button></form></div></div></div></div><?php endforeach;?><?php if(!$assets):?><div class="col-12"><div class="card"><div class="empty-state"><i class="bi bi-star"></i><h2 class="h5 mt-3">No favorites yet</h2><p>Use the Favorite button on any asset.</p><a class="btn btn-primary" href="<?=e(url('assets.php'))?>">Browse assets</a></div></div></div><?php endif;?></div>
<?php require __DIR__.'/includes/footer.php';?>

